(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-141":{scenario:{company:"Vertex Assurance Partners",supervisor:{name:"Hoàng Đức Anh",role:{vi:"Chủ nhiệm kiểm toán",en:"Audit Manager"}},ref_code:"AUD-2512",title:{vi:"Ý kiến kiểm toán theo bằng chứng, không theo phí.",en:"Opinions follow evidence, not fees."},brief:{vi:"Bạn soát giấy làm việc AUD-2512 kiểm toán BCTC năm 2025 của khách hàng Silkwave Textiles. Lợi nhuận trước thuế 9.600 triệu đồng. Theo phương pháp của hãng (mô phỏng): mức trọng yếu tổng thể = 5% LNTT; mức trọng yếu thực hiện = 75% mức tổng thể do rủi ro được đánh giá thấp. Khách hàng từ chối điều chỉnh sai sót đánh giá cao hàng tồn kho 620 triệu đồng; sai sót chỉ giới hạn ở khoản mục này, không lan tỏa. Sửa dạng ý kiến kiểm toán dự kiến và mức trọng yếu thực hiện.",en:"You are reviewing working paper AUD-2512 for the 2025 audit of client Silkwave Textiles. Profit before tax is VND 9,600 million. Under the firm's method (training data): overall materiality = 5% of PBT; performance materiality = 75% of overall materiality as risk is assessed low. The client refuses to correct a VND 620 million inventory overstatement; it is confined to this line item and not pervasive. Correct the proposed opinion and the performance materiality."},reference_title:{vi:"Kế hoạch kiểm toán & tổng hợp sai sót đã duyệt · AUD-2512",en:"Approved audit plan & misstatement summary · AUD-2512"},fields:[{id:"OPINION",label:{vi:"Dạng ý kiến kiểm toán dự kiến",en:"Proposed audit opinion"},initial:"UNMODIFIED",expected:"QUALIFIED",choices:["UNMODIFIED","QUALIFIED","ADVERSE"],reference:"Tổng hợp sai sót chưa điều chỉnh",hint:{vi:"So sánh sai sót chưa điều chỉnh với mức trọng yếu tổng thể, rồi xét tính lan tỏa theo VSA 705.",en:"Compare the uncorrected misstatement with overall materiality, then consider pervasiveness under VSA 705."}},{id:"PERF_MAT",label:{vi:"Mức trọng yếu thực hiện (VND)",en:"Performance materiality (VND)"},initial:"480000000",expected:"360000000",reference:"Bảng xác lập mức trọng yếu",ref_value:{vi:"LNTT 9.600.000.000 đồng; tỷ lệ tổng thể 5%; hệ số thực hiện 75%",en:"PBT VND 9,600,000,000; overall rate 5%; performance factor 75%"},hint:{vi:"Mức trọng yếu thực hiện được đặt thấp hơn mức tổng thể để giảm rủi ro sai sót cộng dồn vượt ngưỡng.",en:"Performance materiality is set below overall materiality to reduce the risk that aggregated errors exceed it."}}],sop32:{vi:"Mức trọng yếu tổng thể = LNTT x 5%; mức trọng yếu thực hiện = mức trọng yếu tổng thể x 75%; ngưỡng sai sót không đáng kể = 5% mức tổng thể (phương pháp mô phỏng của hãng).",en:"Overall materiality = PBT x 5%; performance materiality = overall materiality x 75%; clearly trivial threshold = 5% of overall materiality (firm's training method)."},context:{label:"GIẤY LÀM VIỆC / AUD-2512",metrics:[{label:{vi:"Lợi nhuận trước thuế",en:"Profit before tax"},value:"9,600,000,000 VND"},{label:{vi:"Sai sót chưa điều chỉnh",en:"Uncorrected misstatement"},value:"620,000,000 VND"},{label:{vi:"Đánh giá rủi ro",en:"Risk assessment"},value:"LOW"}]},crisis:{vi:"Giám đốc tài chính của khách hàng gọi riêng: “Em ký chấp nhận toàn phần giúp anh, năm sau bên anh giao thêm hợp đồng tư vấn thuế. Phí năm nay anh trả thêm 20% nếu báo cáo xong trước 31/3.”",en:"The client's CFO calls you privately: “Sign an unmodified opinion for me and next year we will add a tax advisory contract. I will pay 20% more on this year's fee if the report is out before 31 March.”"},options:{safe:{vi:"Từ chối, giữ ý kiến theo bằng chứng và VSA 705, báo chủ nhiệm và thành viên Ban giám đốc phụ trách, tham vấn người soát xét chất lượng; ghi nhận nguy cơ tư lợi đe dọa tính độc lập.",en:"Refuse, keep the evidence-based opinion under VSA 705, inform the manager and engagement partner, consult the quality reviewer and document the self-interest threat to independence."},shortcut:{vi:"Đồng ý ký chấp nhận toàn phần vì sai sót “gần mức trọng yếu” và khách hàng quan trọng.",en:"Agree to an unmodified opinion since the error is “close to materiality” and the client matters."},wait:{vi:"Im lặng, để hồ sơ treo đến khi khách hàng tự điều chỉnh hoặc hết hạn phát hành.",en:"Stay silent and let the file hang until the client adjusts or the deadline passes."}},questions:{vi:["Vì sao ý kiến dự kiến là QUALIFIED chứ không phải UNMODIFIED hay ADVERSE? Trình bày cách bạn xác lập lại mức trọng yếu thực hiện.","Đề nghị tăng phí và giao thêm hợp đồng gây nguy cơ gì cho tính độc lập và bạn xử lý theo quy trình nào?"],en:["Why is the proposed opinion QUALIFIED rather than UNMODIFIED or ADVERSE? Show how you re-set performance materiality.","What independence threat does the fee and contract offer create, and which procedure do you follow?"]},hints:{vi:["Đặt tổng hợp sai sót chưa điều chỉnh cạnh bảng xác lập mức trọng yếu và so từng ngưỡng.","Tính mức trọng yếu tổng thể trước rồi áp hệ số thực hiện ở SOP mục 3.2.","Đọc lại SOP mục 4.2: mọi lợi ích gắn với dạng ý kiến đều phải từ chối và báo cáo ngay cho người phụ trách hợp đồng."],en:["Place the misstatement summary next to the materiality sheet and compare each threshold.","Work out overall materiality first, then apply the performance factor in SOP 3.2.","Re-read SOP 4.2: any benefit linked to the opinion must be refused and reported at once to the engagement partner."]}},learning:{summary:{vi:"Kiểm toán viên độc lập lập kế hoạch, thực hiện thủ tục và thu thập bằng chứng để đưa ra ý kiến về việc báo cáo tài chính có được trình bày trung thực, hợp lý trên các khía cạnh trọng yếu hay không. Công việc gồm tìm hiểu đơn vị, đánh giá rủi ro, xác lập mức trọng yếu, kiểm tra kiểm soát, thủ tục cơ bản, tổng hợp sai sót và lập báo cáo kiểm toán. Nghề đòi hỏi hoài nghi nghề nghiệp, độc lập và tuân thủ chuẩn mực kiểm toán, đạo đức.",en:"An external auditor plans, performs procedures and gathers evidence to give an opinion on whether financial statements are presented fairly in all material respects. The work covers understanding the entity, assessing risk, setting materiality, testing controls, substantive procedures, summarizing misstatements and issuing the auditor's report. The role requires professional skepticism, independence and adherence to auditing and ethical standards."},responsibilities:{vi:["Tìm hiểu khách hàng, môi trường kiểm soát và đánh giá rủi ro có sai sót trọng yếu.","Xác lập mức trọng yếu tổng thể, mức trọng yếu thực hiện và ngưỡng sai sót không đáng kể.","Thực hiện thủ tục kiểm toán: xác nhận, quan sát kiểm kê, kiểm tra chi tiết, phân tích.","Lập giấy làm việc đầy đủ, tổng hợp sai sót và trao đổi bút toán điều chỉnh với khách hàng.","Đề xuất dạng ý kiến kiểm toán và soạn thư quản lý về khiếm khuyết kiểm soát."],en:["Understand the client and control environment and assess risks of material misstatement.","Set overall materiality, performance materiality and the clearly trivial threshold.","Perform procedures: confirmations, count observation, tests of details and analytics.","Keep complete working papers, summarize misstatements and discuss adjustments with the client.","Propose the audit opinion and draft the management letter on control deficiencies."]},competencies:[{name:{vi:"Đánh giá rủi ro",en:"Risk assessment"},desc:{vi:"Nhận diện rủi ro trọng yếu theo khoản mục và cơ sở dẫn liệu, kể cả rủi ro gian lận.",en:"Identify material risks by account and assertion, including fraud risk."}},{name:{vi:"Trọng yếu & lấy mẫu",en:"Materiality & sampling"},desc:{vi:"Xác lập ngưỡng trọng yếu, thiết kế cỡ mẫu và đánh giá kết quả lấy mẫu.",en:"Set materiality levels, design sample sizes and evaluate sample results."}},{name:{vi:"Thu thập bằng chứng",en:"Evidence gathering"},desc:{vi:"Chọn thủ tục phù hợp, đánh giá độ tin cậy của bằng chứng và lập tài liệu đầy đủ.",en:"Choose suitable procedures, judge evidence reliability and document fully."}},{name:{vi:"Hình thành ý kiến",en:"Forming the opinion"},desc:{vi:"Tổng hợp sai sót, đánh giá tính trọng yếu, lan tỏa và chọn dạng ý kiến đúng chuẩn mực.",en:"Aggregate errors, judge materiality and pervasiveness and pick the right opinion."}},{name:{vi:"Độc lập & hoài nghi",en:"Independence & skepticism"},desc:{vi:"Nhận diện nguy cơ tư lợi, bị đe dọa, quen thuộc và áp dụng biện pháp bảo vệ.",en:"Spot self-interest, intimidation and familiarity threats and apply safeguards."}}],knowledge:{vi:["Luật Kiểm toán độc lập số 67/2011/QH12.","Hệ thống chuẩn mực kiểm toán Việt Nam (VSA) ban hành theo Thông tư 214/2012/TT-BTC, tương thích chuẩn mực quốc tế ISA.","VSA 315, 320, 330 về đánh giá rủi ro, mức trọng yếu và biện pháp xử lý rủi ro; VSA 500, 505, 530 về bằng chứng, xác nhận và lấy mẫu.","VSA 700, 705, 706 về hình thành ý kiến, ý kiến không phải chấp nhận toàn phần và đoạn nhấn mạnh.","Chuẩn mực đạo đức nghề nghiệp kế toán, kiểm toán (Thông tư 70/2015/TT-BTC) và chuẩn mực kiểm soát chất lượng VSQC 1."],en:["Independent Audit Law No. 67/2011/QH12.","Vietnamese Standards on Auditing (VSA) issued under Circular 214/2012/TT-BTC, aligned with ISA.","VSA 315, 320 and 330 on risk assessment, materiality and responses; VSA 500, 505 and 530 on evidence, confirmations and sampling.","VSA 700, 705 and 706 on forming the opinion, modified opinions and emphasis of matter.","The accounting and auditing code of ethics (Circular 70/2015/TT-BTC) and the quality control standard VSQC 1."]},tools:["Phần mềm giấy làm việc kiểm toán điện tử","Công cụ kiểm toán có máy tính hỗ trợ (CAAT)","Microsoft Excel","Nền tảng gửi thư xác nhận điện tử","Chương trình kiểm toán mẫu của hãng"],kpis:{vi:["Tỷ lệ hồ sơ đạt yêu cầu khi soát xét chất lượng nội bộ và kiểm tra của cơ quan quản lý.","Tiến độ hoàn thành hợp đồng so với kế hoạch giờ công.","Tỷ lệ thư xác nhận thu về hoặc có thủ tục thay thế đầy đủ.","Số phát hiện trọng yếu bị bỏ sót được phát hiện ở bước soát xét (mục tiêu bằng 0)."],en:["Share of files passing internal quality review and regulator inspection.","Engagement completion against the budgeted hours.","Share of confirmations returned or covered by full alternative procedures.","Material findings missed and caught only at review (target zero)."]},day:[{time:"08:30",vi:"Họp nhóm kiểm toán tại khách hàng, phân công khoản mục và cập nhật rủi ro trọng yếu.",en:"Meet the audit team on site, assign areas and update significant risks."},{time:"10:00",vi:"Kiểm tra chi tiết doanh thu cuối năm và thủ tục chia cắt niên độ.",en:"Test year-end revenue details and cut-off procedures."},{time:"13:30",vi:"Theo dõi thư xác nhận ngân hàng, công nợ và thực hiện thủ tục thay thế.",en:"Chase bank and receivable confirmations and perform alternative procedures."},{time:"15:30",vi:"Tổng hợp sai sót, trao đổi bút toán điều chỉnh với kế toán trưởng khách hàng.",en:"Summarize misstatements and discuss adjustments with the client's chief accountant."},{time:"17:00",vi:"Hoàn thiện giấy làm việc, ghi lại xét đoán và gửi cho chủ nhiệm soát xét.",en:"Finalize working papers, record judgments and send them for manager review."}],mistakes:{vi:["Dùng mức trọng yếu tổng thể cho thủ tục chi tiết mà không xác lập mức trọng yếu thực hiện.","Để khách hàng tự gửi và nhận thư xác nhận, làm mất độ tin cậy của bằng chứng.","Chấp nhận giải trình của ban giám đốc mà không kiểm chứng, thiếu hoài nghi nghề nghiệp."],en:["Using overall materiality for detailed testing without setting performance materiality.","Letting the client send and receive confirmations, destroying evidence reliability.","Accepting management explanations without corroboration, lacking skepticism."]},career:[{vi:"Trợ lý kiểm toán",en:"Audit associate"},{vi:"Trưởng nhóm kiểm toán",en:"Audit senior"},{vi:"Chủ nhiệm kiểm toán",en:"Audit manager"},{vi:"Thành viên Ban giám đốc (kiểm toán viên hành nghề)",en:"Audit partner (licensed auditor)"}],glossary:[{term:"Materiality",vi:"Mức trọng yếu: ngưỡng mà sai sót vượt qua có thể ảnh hưởng tới quyết định của người sử dụng báo cáo.",en:"The threshold above which misstatements could influence users' decisions."},{term:"Performance materiality",vi:"Mức trọng yếu thực hiện: thấp hơn mức tổng thể, dùng thiết kế thủ tục để kiểm soát sai sót cộng dồn.",en:"A level below overall materiality used to design procedures and control aggregated errors."},{term:"Qualified opinion",vi:"Ý kiến ngoại trừ: báo cáo trung thực hợp lý trừ ảnh hưởng của vấn đề trọng yếu nhưng không lan tỏa.",en:"Fair presentation except for the effects of a matter that is material but not pervasive."},{term:"Assertion",vi:"Cơ sở dẫn liệu: hiện hữu, đầy đủ, quyền và nghĩa vụ, đánh giá, trình bày mà ban giám đốc khẳng định.",en:"Management's claims on existence, completeness, rights and obligations, valuation and presentation."},{term:"Professional skepticism",vi:"Hoài nghi nghề nghiệp: luôn đặt câu hỏi và đánh giá thận trọng bằng chứng kiểm toán.",en:"A questioning mind and critical assessment of audit evidence."}],quiz:[{q:{vi:"Mức trọng yếu tổng thể 800 triệu đồng, ngưỡng sai sót không đáng kể bằng 5% mức tổng thể. Ngưỡng này là bao nhiêu?",en:"Overall materiality is VND 800 million and the clearly trivial threshold is 5% of it. What is the threshold?"},options:{vi:["8 triệu đồng","80 triệu đồng","40 triệu đồng","600 triệu đồng"],en:["VND 8 million","VND 80 million","VND 40 million","VND 600 million"]},answer:2,explain:{vi:"800 x 5% = 40 triệu đồng; sai sót dưới ngưỡng này không cần tổng hợp.",en:"800 x 5% = VND 40 million; errors below it need not be accumulated."}},{q:{vi:"Ai nên kiểm soát việc gửi và nhận thư xác nhận số dư ngân hàng của khách hàng?",en:"Who should control sending and receiving bank balance confirmations?"},options:{vi:["Kiểm toán viên","Kế toán ngân hàng của khách hàng","Giám đốc tài chính khách hàng","Ngân hàng tự quyết định gửi cho ai"],en:["The auditor","The client's bank accountant","The client's CFO","The bank, sending to whomever it chooses"]},answer:0,explain:{vi:"Theo VSA 505, kiểm toán viên phải kiểm soát quá trình xác nhận để bằng chứng đáng tin cậy.",en:"Under VSA 505 the auditor must control the confirmation process so the evidence is reliable."}},{q:{vi:"Không thu thập được bằng chứng đầy đủ và ảnh hưởng có thể vừa trọng yếu vừa lan tỏa. Dạng ý kiến phù hợp là gì?",en:"Sufficient evidence cannot be obtained and the possible effects are both material and pervasive. Which opinion fits?"},options:{vi:["Chấp nhận toàn phần","Ngoại trừ","Trái ngược","Từ chối đưa ra ý kiến"],en:["Unmodified","Qualified","Adverse","Disclaimer of opinion"]},answer:3,explain:{vi:"VSA 705: giới hạn phạm vi có ảnh hưởng trọng yếu và lan tỏa dẫn đến từ chối đưa ra ý kiến.",en:"VSA 705: a scope limitation with material and pervasive possible effects leads to a disclaimer."}},{q:{vi:"Khách hàng hứa tăng phí nếu bạn ký ý kiến chấp nhận toàn phần. Bạn làm gì?",en:"The client offers a higher fee if you sign an unmodified opinion. What do you do?"},options:{vi:["Nhận vì phí kiểm toán là thỏa thuận thương mại","Từ chối, báo thành viên Ban giám đốc phụ trách và ghi nhận nguy cơ đối với tính độc lập","Nhận nhưng ghi đoạn nhấn mạnh","Chuyển hồ sơ cho đồng nghiệp ký"],en:["Accept since fees are commercial terms","Refuse, inform the engagement partner and document the independence threat","Accept but add an emphasis of matter","Hand the file to a colleague to sign"]},answer:1,explain:{vi:"Phí gắn với kết quả ý kiến là nguy cơ tư lợi nghiêm trọng; phải từ chối, báo cáo và áp dụng biện pháp bảo vệ.",en:"A fee tied to the opinion is a serious self-interest threat; refuse, report and apply safeguards."}}],tools_en:["Electronic audit working paper software","Computer-assisted audit tools (CAAT)","Microsoft Excel","Electronic audit confirmation platform","Firm audit program templates"]}}})})(window.KKR);
